var REGIONS = {"marmara":{"name":{"de":"Marmara & Istanbul"},"tag":{"de":"Zwei Kontinente, drei Weltreiche — und die Mauern von Troja"}},"aegean":{"name":{"de":"Ägäisküste"},"tag":{"de":"Antike Marmorstädte, Thermalterrassen und weiße Hafenstädtchen"}},"med":{"name":{"de":"Mittelmeer — die Türkisküste"},"tag":{"de":"Pinienlagunen, lykische Ruinen und 300 Sonnentage im Jahr"}},"central":{"name":{"de":"Zentralanatolien"},"tag":{"de":"Feenkamine, unterirdische Städte und die Heimat der tanzenden Derwische"}},"north":{"name":{"de":"Schwarzmeerregion"},"tag":{"de":"Felsenklöster, Teegärten und perfekt erhaltene osmanische Städte"}},"east":{"name":{"de":"Ostanatolien"},"tag":{"de":"Hochebenen, eine Geisterhauptstadt und Kircheninseln in einem Sodasee"}},"southeast":{"name":{"de":"Südostanatolien"},"tag":{"de":"Mesopotamien: der erste Tempel der Welt und Städte älter als die Geschichte"}}};
var D = [{"id":"hagia","img":"https://api.bubixo.com/discover-turkiye/assets/hagia.jpg","region":"marmara","unesco":true,"name":{"de":"Hagia Sophia"},"desc":{"de":"537 n. Chr. als größte Kathedrale von Byzanz erbaut, später kaiserliche Moschee — fast tausend Jahre lang war dies der größte überdachte Raum der Welt. Die schwebende goldene Kuppel und die vielschichtige Geschichte machen sie zum berühmtesten Bauwerk der Türkei."},"loc":{"de":"Sultanahmet, Istanbul"},"best":{"de":"Apr–Jun & Sep–Nov; direkt zur Öffnung"},"tip":{"de":"Touristen besichtigen die obere Galerie (Ticket ≈ 25 €); während der Gebetszeiten geschlossen."}},{"id":"blue","img":"https://api.bubixo.com/discover-turkiye/assets/blue.jpg","region":"marmara","unesco":true,"name":{"de":"Blaue Moschee & Sultanahmet"},"desc":{"de":"Die Sultan-Ahmed-Moschee mit ihren sechs Minaretten und 20.000 handgefertigten İznik-Fliesen liegt der Hagia Sophia direkt gegenüber. Ringsum erstreckt sich das alte Kaiserviertel: Topkapı-Palast, Cisterna Basilica und der Große Basar mit 4.000 Läden."},"loc":{"de":"Sultanahmet, Istanbul"},"best":{"de":"Ganzjährig; Abenddämmerung für Fotos"},"tip":{"de":"Eintritt frei, außerhalb der fünf Gebetszeiten. Angemessene Kleidung; Tücher gibt es am Eingang."}},{"id":"galata","img":"https://api.bubixo.com/discover-turkiye/assets/galata.jpg","region":"marmara","unesco":false,"name":{"de":"Galata & der Bosporus"},"desc":{"de":"Über die Galatabrücke, vorbei an Anglern und Fischbrötchen, hinauf auf den genuesischen Turm aus dem 14. Jh. mit 360°-Panorama — und dann per Fähre über die Meerenge zwischen Europa und Asien: die günstigste Weltklasse-Kreuzfahrt überhaupt."},"loc":{"de":"Karaköy / Beyoğlu, Istanbul"},"best":{"de":"Ganzjährig; Fähre bei Sonnenuntergang"},"tip":{"de":"Mit der Istanbulkart fahren Sie Fähre, Tram und Metro — Linienfähren schlagen teure Touristenboote."}},{"id":"troy","img":"https://api.bubixo.com/discover-turkiye/assets/troy.jpg","region":"marmara","unesco":true,"name":{"de":"Troja"},"desc":{"de":"Die legendäre Stadt aus Homers Ilias — Archäologen fanden hier neun übereinanderliegende Städte aus 4.000 Jahren. Über die antiken Mauern spazieren, mit dem Holzpferd posieren und dann ins beeindruckende moderne Troja-Museum nebenan."},"loc":{"de":"Bei Çanakkale, Dardanellen"},"best":{"de":"Apr–Jun & Sep–Okt"},"tip":{"de":"Mit den bewegenden Schlachtfeldern von Gallipoli auf der anderen Seite der Meerenge zu einem ganzen Geschichtstag verbinden."}},{"id":"cappadocia","img":"https://api.bubixo.com/discover-turkiye/assets/cappadocia.jpg","region":"central","unesco":true,"name":{"de":"Kappadokien"},"desc":{"de":"Eine surreale Vulkanlandschaft aus Feenkaminen, byzantinischen Höhlenkirchen und ganzen unterirdischen Städten. Im Morgengrauen schweben über hundert Heißluftballons über die Täler von Göreme — eines der großen Reiseschauspiele der Welt."},"loc":{"de":"Göreme / Nevşehir, Zentralanatolien"},"best":{"de":"Apr–Jun & Sep–Nov für Ballonfahrten"},"tip":{"de":"Ballonfahrt vorab buchen und 2–3 Morgen einplanen — bei Wind wird abgesagt. Übernachten Sie im Höhlenhotel."}},{"id":"pamukkale","img":"https://api.bubixo.com/discover-turkiye/assets/pamukkale.jpg","region":"aegean","unesco":true,"name":{"de":"Pamukkale & Hierapolis"},"desc":{"de":"Die „Baumwollburg“: ein Hang aus blendend weißen Travertin-Terrassen voll warmem Thermalwasser. Auf dem Plateau darüber liegen die Ruinen des römischen Hierapolis — im Kleopatra-Becken schwimmt man zwischen versunkenen antiken Säulen."},"loc":{"de":"Bei Denizli, Ägäisregion"},"best":{"de":"Früher Morgen oder goldene Stunde"},"tip":{"de":"Auf den Terrassen gilt Barfußpflicht — Beutel für die Schuhe mitnehmen, der Stein kann rutschig sein."}},{"id":"ephesus","img":"https://api.bubixo.com/discover-turkiye/assets/ephesus.jpg","region":"aegean","unesco":true,"name":{"de":"Ephesos"},"desc":{"de":"Die besterhaltene antike Stadt des östlichen Mittelmeers. Marmorstraßen führen an der zweistöckigen Celsus-Bibliothek, römischen Hanghäusern mit intakten Fresken und einem Theater für 25.000 Zuschauer vorbei."},"loc":{"de":"Selçuk, bei İzmir"},"best":{"de":"Mär–Mai & Sep–Nov; erste Stunde nach Öffnung"},"tip":{"de":"Nehmen Sie einen Guide oder Audioguide — dann leben die Steine. Die Hanghäuser (Extraticket) nicht auslassen."}},{"id":"oludeniz","img":"https://api.bubixo.com/discover-turkiye/assets/oludeniz.jpg","region":"med","unesco":false,"name":{"de":"Ölüdeniz & Fethiye"},"desc":{"de":"Eine stille, türkisfarbene Lagune um eine weiße Sandzunge unter Pinienbergen — der meistfotografierte Strand der Türkei. Tandem-Gleitschirme starten vom 1.900 m hohen Babadağ; der Lykische Weg beginnt gleich nebenan."},"loc":{"de":"Fethiye, Türkisküste"},"best":{"de":"Mai–Okt; ideal im Juni & September"},"tip":{"de":"Gleitschirmflug morgens buchen (ruhigere Luft) und einen Bootsausflug ins Schmetterlingstal machen."}},{"id":"antalya","img":"https://api.bubixo.com/discover-turkiye/assets/antalya.jpg","region":"med","unesco":false,"name":{"de":"Antalya"},"desc":{"de":"Die Hauptstadt der Türkischen Riviera: die osmanische Altstadt Kaleiçi um einen römischen Hafen, Wasserfälle, die direkt ins Meer stürzen, lange Strände vor dem Taurusgebirge. Perge, Aspendos und Side liegen ganz in der Nähe."},"loc":{"de":"Mittelmeerküste"},"best":{"de":"Apr–Jun & Sep–Nov; Baden bis in den November"},"tip":{"de":"Den Unteren Düden-Wasserfall vom Boot aus ansehen und im Sommer ein Konzert im römischen Theater von Aspendos erleben."}},{"id":"bodrum","img":"https://api.bubixo.com/discover-turkiye/assets/bodrum.jpg","region":"aegean","unesco":false,"name":{"de":"Bodrum"},"desc":{"de":"Weißgetünchte Häuser und Bougainvillea ziehen sich hinab zur Bucht mit der Burg St. Peter, die ein Weltklasse-Museum für Unterwasserarchäologie beherbergt. Hier stand einst das Mausoleum von Halikarnassos, eines der Sieben Weltwunder."},"loc":{"de":"Halbinsel Bodrum, Ägäis"},"best":{"de":"Mai–Okt; im Hochsommer am lebhaftesten"},"tip":{"de":"Chartern Sie eine traditionelle Gulet für eine „Blaue Reise“ entlang der Küste — schon ein Tagestörn lohnt sich."}},{"id":"side","img":"https://api.bubixo.com/discover-turkiye/assets/side.jpg","region":"med","unesco":false,"name":{"de":"Side & Aspendos"},"desc":{"de":"Eine griechisch-römische Hafenstadt auf einer kleinen Halbinsel — die Marmorsäulen des Apollon-Tempels rahmen den Sonnenuntergang über dem Meer. Im nahen Aspendos steht das besterhaltene römische Theater der Welt, noch heute Bühne für Aufführungen."},"loc":{"de":"Manavgat, östlich von Antalya"},"best":{"de":"Apr–Jun & Sep–Nov; Sonnenuntergang am Tempel"},"tip":{"de":"Die Ruinen durchziehen das heutige Dorf — schlendern Sie die Säulenstraße hinunter zum alten Hafen."}},{"id":"konya","img":"https://api.bubixo.com/discover-turkiye/assets/konya.jpg","region":"central","unesco":false,"name":{"de":"Konya & das Mevlâna"},"desc":{"de":"Das spirituelle Herz der Türkei: Hier lehrte der Sufi-Dichter Rumi im 13. Jahrhundert und ruht unter einer türkisgekachelten Kuppel. Sein Mausoleum-Museum und die hypnotische Sema-Zeremonie der tanzenden Derwische ziehen Pilger aller Glaubensrichtungen an."},"loc":{"de":"Konya, Zentralanatolien"},"best":{"de":"Ganzjährig; Rumi-Festival im Dezember"},"tip":{"de":"Eine authentische Sema-Zeremonie erleben (samstags im Mevlâna-Kulturzentrum) und Etli Ekmek probieren, Konyas meterlanges Fladenbrot."}},{"id":"gobekli","img":"https://api.bubixo.com/discover-turkiye/assets/gobekli.jpg","region":"southeast","unesco":true,"name":{"de":"Göbekli Tepe"},"desc":{"de":"Der älteste bekannte Monumentaltempel der Welt, um 9600 v. Chr. von Jägern und Sammlern errichtet — rund 6.000 Jahre vor Stonehenge. Ringe T-förmiger Megalithen mit Füchsen, Geiern und Skorpionen schreiben die Geschichte der Zivilisation neu."},"loc":{"de":"Bei Şanlıurfa, Südosten"},"best":{"de":"Mär–Mai & Okt–Nov; Sommer sind glühend heiß"},"tip":{"de":"Kombinieren Sie den Besuch mit dem großartigen Archäologiemuseum von Şanlıurfa und den Karpfenteichen von Balıklıgöl."}},{"id":"nemrut","img":"https://api.bubixo.com/discover-turkiye/assets/nemrut.jpg","region":"southeast","unesco":true,"name":{"de":"Berg Nemrut"},"desc":{"de":"Auf einem 2.134 m hohen Gipfel ließ ein vergessener König von Kommagene sein Grabheiligtum errichten, bewacht von kolossalen Steinköpfen. Bei Sonnenauf- und -untergang glühen die Statuen orange über einem Meer aus Bergen — wie von einer anderen Welt."},"loc":{"de":"Adıyaman, Osttaurus"},"best":{"de":"Mai–Okt (Straße im Winter gesperrt)"},"tip":{"de":"Zum Sonnenaufgang hinauf, auch im August warme Kleidung mitnehmen — der Gipfelwind ist eisig. Basis: Kahta oder Karadut."}},{"id":"sumela","img":"https://api.bubixo.com/discover-turkiye/assets/sumela.jpg","region":"north","unesco":false,"name":{"de":"Kloster Sumela"},"desc":{"de":"Ein im 4. Jahrhundert gegründetes griechisch-orthodoxes Kloster, das sich in eine senkrechte Felswand schmiegt, 300 Meter über einem nebligen Waldtal. Innen leuchten restaurierte Fresken, draußen die grünste Landschaft der Schwarzmeerregion."},"loc":{"de":"Altındere-Tal, bei Trabzon"},"best":{"de":"Mai–Okt; oft in stimmungsvollen Nebel gehüllt"},"tip":{"de":"Mit dem Bergsee Uzungöl und einer Teepause kombinieren — hier wächst der gesamte Tee der Türkei."}},{"id":"ani","img":"https://api.bubixo.com/discover-turkiye/assets/ani.jpg","region":"east","unesco":true,"name":{"de":"Ani"},"desc":{"de":"Die ergreifenden Ruinen einer mittelalterlichen armenischen Hauptstadt — die „Stadt der 1001 Kirchen“ — verstreut über eine Steppenlandschaft am äußersten Rand der Türkei. Vor tausend Jahren Rivale Konstantinopels, heute fast menschenleer."},"loc":{"de":"45 km von Kars, Nordosten"},"best":{"de":"Mai–Sep; der Winter ist karg, aber schön"},"tip":{"de":"Mindestens einen halben Tag einplanen und gutes Schuhwerk tragen — das Gelände ist riesig. Kars ist für Honig und Gravyer-Käse berühmt."}},{"id":"van","img":"https://api.bubixo.com/discover-turkiye/assets/van.jpg","region":"east","unesco":false,"name":{"de":"Vansee & Akdamar"},"desc":{"de":"Der größte See der Türkei — ein weites, sodablaues Binnenmeer, umringt von Vulkanen. Eine kurze Bootsfahrt führt zur Insel Akdamar mit ihrer armenischen Heilig-Kreuz-Kirche aus dem 10. Jahrhundert voller lebendiger biblischer Reliefs."},"loc":{"de":"Van, äußerster Osten"},"best":{"de":"Mai–Sep; Mandelblüte im April"},"tip":{"de":"Beginnen Sie den Tag mit einem legendären Van-Frühstück — Dutzende Tellerchen mit Käse, Honig und Kaymak."}},{"id":"mardin","img":"https://api.bubixo.com/discover-turkiye/assets/mardin.jpg","region":"southeast","unesco":false,"name":{"de":"Mardin"},"desc":{"de":"Honigfarbene Steinhäuser ziehen sich einen Hang hinab, über der endlosen mesopotamischen Ebene. Minarette, uralte syrisch-orthodoxe Klöster, Silberfiligran-Werkstätten und Hofcafés machen Mardin zur stimmungsvollsten Stadt des Südostens."},"loc":{"de":"Südostanatolien"},"best":{"de":"Mär–Mai & Sep–Nov"},"tip":{"de":"Besuchen Sie das Safran-Kloster Deyrulzafaran zur goldenen Stunde und übernachten Sie in einem restaurierten Steinpalais."}},{"id":"safranbolu","img":"https://api.bubixo.com/discover-turkiye/assets/safranbolu.jpg","region":"north","unesco":true,"name":{"de":"Safranbolu"},"desc":{"de":"Eine perfekt erhaltene osmanische Handelsstadt mit Fachwerkvillen, Kopfsteingassen, einer Karawanserei aus dem 17. Jh. und Handwerksbasaren — benannt nach dem Safran, der hier noch immer auf den Feldern wächst."},"loc":{"de":"Karabük, ca. 2 Std. von Ankara"},"best":{"de":"Apr–Okt; auch unter Winterschnee reizvoll"},"tip":{"de":"In einem Konak (osmanischen Herrenhaus) übernachten, Safran-Lokum probieren und für den Dächerblick auf den Hıdırlık-Hügel steigen."}},{"id":"uzungol","img":"https://api.bubixo.com/discover-turkiye/assets/uzungol.jpg","region":"north","unesco":false,"name":{"de":"Uzungöl"},"desc":{"de":"Ein spiegelglatter Bergsee auf 1.090 m, mit einer Moschee am Ufer und Fichtenwald, der in den Nebel steigt — das Postkartenmotiv der Schwarzmeerregion und selbst im Hochsommer angenehm kühl."},"loc":{"de":"Çaykara, Trabzon"},"best":{"de":"Mai–Okt; neblige Morgen sind der Zauber"},"tip":{"de":"Übernachten Sie — der See ist am stillsten, bevor die Tagesbusse kommen und nachdem sie fort sind."}}];
