var TIPS = [{"ico":"M2 12h20M12 2a15 15 0 0 1 0 20 15 15 0 0 1 0-20zM12 2a15 15 0 0 0 0 20","h":{"de":"Visum & Einreise"},"p":{"de":"Viele Nationalitäten reisen visumfrei ein oder mit einem schnellen e-Visum über die offizielle Seite evisa.gov.tr. Prüfen Sie die Regeln für Ihren Pass vor der Buchung."}},{"ico":"M12 1v22M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6","h":{"de":"Geld"},"p":{"de":"Die Währung ist die Türkische Lira (₺). Karten werden fast überall akzeptiert; für Basare, Taxis und Trinkgeld etwas Bargeld bereithalten — Handeln gehört auf dem Basar dazu."}},{"ico":"M4 21V8l8-5 8 5v13M9 21v-6h6v6","h":{"de":"Moschee-Etikette"},"p":{"de":"Moscheen können außerhalb der Gebetszeiten kostenlos besucht werden. Schultern und Knie bedecken, Schuhe ausziehen, Kopftuch für Frauen (meist vorhanden). Leise sprechen."}},{"ico":"M2.5 19.5L21 12 2.5 4.5l3.5 7.5-3.5 7.5zM6 12h15","h":{"de":"Unterwegs im Land"},"p":{"de":"Die Distanzen sind groß: günstige Inlandsflüge (THY, Pegasus, AJet) verbinden alle Regionen, Fernbusse sind exzellent, Schnellzüge verkehren zwischen Istanbul, Ankara und Konya."}},{"ico":"M3 11l9-8 9 8M5 9v11h14V9M9 20v-7h6v7","h":{"de":"Museumspass"},"p":{"de":"Der offizielle Museum Pass Türkiye (muze.gov.tr) gilt für Hunderte staatliche Stätten — Ephesos, Göbekli Tepe, Topkapı u. v. m. — und erspart die Ticketschlangen."}},{"ico":"M18 8a6 6 0 1 1-12 0M12 14v7M8 21h8M5 8h14","h":{"de":"Essen & Teekultur"},"p":{"de":"Sagen Sie Ja zum Çay — Tee ist die Sprache der Gastfreundschaft. Probieren Sie ein türkisches Frühstück, Simit, Pide, Meze am Meer und Baklava mit Pistazien aus Gaziantep."}}];
var DETAILS = {"hagia":{"long":{"de":["Kaiser Justinian soll seine vollendete Kathedrale 537 n. Chr. betreten und geflüstert haben: „Salomon, ich habe dich übertroffen.“ Neun Jahrhunderte lang war die Hagia Sophia das Herz des byzantinischen Christentums; nach 1453 wurde sie zur Hauptmoschee der Osmanen, die Minarette, Kalligrafie-Medaillons und eine Sultansloge hinzufügten — und die goldenen Mosaiken sorgsam bewahrten. So teilen sich heute eine Mosaik-Madonna und die Namen der Kalifen dieselbe Kuppel. Nichts auf der Welt sieht so aus.","Innen scheint die 31-Meter-Kuppel auf einem Lichtring zu schweben — Zeitgenossen behaupteten, sie hänge an einer goldenen Kette vom Himmel. Achten Sie auf das schimmernde Deesis-Mosaik in der oberen Galerie, die Wikinger-Runen, die ein gelangweilter Söldner vor tausend Jahren in eine Marmorbrüstung ritzte, und die „Wunschsäule“ mit ihrem blank geriebenen Daumenloch. Kommen Sie früh — und beobachten Sie abends von einem Dachcafé, wie die Möwen die Minarette umkreisen."]},"getting":{"de":"Tram T1 bis Sultanahmet; 15 Min. zu Fuß von Sirkeci. Von den Flughäfen mit Metro M1/M11 oder Havaist-Bus in die Altstadt."},"eat":{"de":"Probieren Sie die traditionsreichen Köfte-Lokale an der Divanyolu-Straße, danach Baklava und Lokum in einer historischen Süßwarenhandlung bei Sirkeci."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/hagia-1.jpg","cap":{"de":"Der Bau aus dem 6. Jh. mit seinen osmanischen Minaretten"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/hagia-2.jpg","cap":{"de":"Die Fassade vom Sultanahmet-Platz aus"}}]},"blue":{"long":{"de":["Sultan Ahmed I. war erst neunzehn, als er eine Moschee in Auftrag gab, die es mit der Hagia Sophia gegenüber aufnehmen sollte. Ihre Fertigstellung 1616 löste in Mekka einen Skandal aus: Sechs Minarette — so viele wie die Große Moschee selbst, weshalb dort ein siebtes gebaut werden musste. Der Beiname „Blaue Moschee“ kommt vom Inneren: über 20.000 handgefertigte İznik-Fliesen mit Tulpen-, Nelken- und Zypressenmustern, leuchtend unter 260 Fenstern.","Die Moschee ist das Herz eines Viertels, das Mittelpunkt zweier Weltreiche war. Auf dem Hippodrom davor steht ein ägyptischer Obelisk von 1500 v. Chr.; die Cisterna Basilica verbirgt einen Wald aus 336 römischen Säulen im Halbdunkel; der Topkapı-Palast breitet Höfe, Harem und Schatzkammer über die Spitze der Halbinsel aus; und im Großen Basar — 4.000 Läden unter bemalten Gewölben — wird seit 1461 gefeilscht. Planen Sie für Sultanahmet mindestens zwei volle Tage ein."]},"getting":{"de":"Tram T1 bis Sultanahmet; alles im Viertel ist zu Fuß erreichbar. Eintritt frei außerhalb der Gebetszeiten; angemessene Kleidung erforderlich."},"eat":{"de":"Setzen Sie sich in einen Hof-Teegarten (çay bahçesi) zwischen den beiden großen Moscheen — im Winter Sahlep, im Sommer frischen Granatapfelsaft probieren."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/blue-1.jpg","cap":{"de":"Eine Decke in handbemaltem İznik-Blau"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/blue-2.jpg","cap":{"de":"Der große Innenhof zur stillen Stunde"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/blue-3.jpg","cap":{"de":"Die Cisterna Basilica, fünf Gehminuten entfernt"}}]},"galata":{"long":{"de":["Karaköy und Galata waren das Hafenviertel genuesischer Kaufleute, und ihr Wachturm von 1348 beherrscht noch immer die Silhouette nördlich des Goldenen Horns. Steigen Sie hinauf (oder nehmen Sie den Aufzug) für den klassischen 360°-Blick: auf der einen Seite die Kuppeln der Altstadt, auf der anderen der Bosporus auf seinem Weg zum Schwarzen Meer. Darunter fallen steile Gassen voller Galerien, Kaffeeröstereien und Antiquitätenläden zum Wasser hin ab.","Und dann das beste günstige Erlebnis Istanbuls: eine Linienfähre. Die Überfahrt nach Kadıköy oder eine ganze Bosporus-Rundfahrt gleitet an osmanischen Palästen, Ufervillen und dem Leanderturm vorbei — mit Çay an Deck für ein paar Lira. Kehren Sie bei Sonnenuntergang über die Galatabrücke zurück, wenn Angler die Geländer säumen und unten die Fischbrötchen-Boote ihre Grills anwerfen."]},"getting":{"de":"Metro M2 bis Şişhane, Tram T1 bis Karaköy oder die historische Tünel-Standseilbahn — die zweitälteste U-Bahn der Welt, in Betrieb seit 1875."},"eat":{"de":"Balık Ekmek (gegrilltes Fischbrötchen) an der Brücke, Künefe in den Dessertläden von Karaköy und Third-Wave-Kaffee oben in Galata."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/galata-1.jpg","cap":{"de":"Der Genueserturm über den Dächern Galatas"}}]},"troy":{"long":{"de":["Jahrhundertelang galt Troja als reine Dichtung — bis Heinrich Schliemann in den 1870ern den Hügel von Hisarlık aufgrub und nicht eine Stadt fand, sondern neun, geschichtet wie Buchseiten über 4.000 Jahre. Die Schicht Troja VII, um 1180 v. Chr. durch Feuer zerstört, ist der beste Kandidat für Homers Krieg. Noch heute kann man die geneigten Mauern ablaufen, die den Griechen angeblich zehn Jahre widerstanden, die Rampe betreten, über die einst Streitwagen rollten, und im Heiligtum stehen, wo tausend Jahre vor Rom geopfert wurde.","Die Stätte belohnt Vorstellungskraft — und das preisgekrönte Troja-Museum nebenan liefert sie: Auf vier Etagen erzählen Goldschmuck, Waffen und Sarkophage die Geschichte besser als jeder Reiseführer. Das riesige Holzpferd am Eingang ist reines Theater — klettern Sie trotzdem hinein. Jenseits der Dardanellen liegen die Schlachtfelder von Gallipoli (1915): ein bewegender Nachmittagsausflug, der 3.000 Jahre Krieg um dieselbe Meerenge umspannt."]},"getting":{"de":"30 Min. mit Auto oder Minibus ab Çanakkale (Flug ab Istanbul oder 5–6 Std. mit Bus/Auto über die Gallipoli-Brücke)."},"eat":{"de":"An der Uferpromenade von Çanakkale gibt es hervorragende gegrillte Sardinen und Peynir Helvası, die lokale Käse-Halva — beides nach den Ruinen probieren."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/troy-1.jpg","cap":{"de":"Das Holzpferd an der Uferpromenade von Çanakkale"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/troy-2.jpg","cap":{"de":"Neun Städte in einem Hügel bei Hisarlık"}}]},"ephesus":{"long":{"de":["Ephesos war das New York des römischen Ostens: eine Hafenmetropole mit 200.000 Einwohnern, deren Artemistempel — eines der Sieben Weltwunder — Pilger aus dem gesamten Mittelmeerraum anzog. Paulus predigte (und löste einen Aufruhr aus) im großen Theater; Maria soll ihre letzten Jahre in einem Steinhäuschen auf dem Hügel darüber verbracht haben. Was erhalten ist, verblüfft: von Karrenrädern zerfurchte Marmorstraßen, eine zweistöckige Bibliotheksfassade für 12.000 Schriftrollen, öffentliche Latrinen, ein Bordell und in den Gehweg gemeißelte Werbung.","Lassen Sie die Hanghäuser unter ihrem Schutzdach nicht aus — römische Stadtvillen mit Mosaikböden, Fresken und Zentralheizung, im 3. Jahrhundert mitten in der Renovierung verlassen, als wären die Maler eben erst gegangen. Kommen Sie zur Öffnung oder am späten Nachmittag: Mittags fluten Kreuzfahrtgruppen die Stätte, und der Marmor strahlt im Sommer gewaltige Hitze ab."]},"getting":{"de":"3 km von Selçuk — per Taxi, Dolmuş oder zu Fuß erreichbar. Selçuk liegt 1 Std. mit Zug oder Auto vom Flughafen İzmir entfernt."},"eat":{"de":"Şirince, ein Bergdorf mit alten griechischen Häusern 8 km entfernt, ist ideal für ein langes Mittagessen mit Dorffrühstück, Gözleme und Fruchtweinen."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/ephesus-1.jpg","cap":{"de":"Das große Theater mit 25.000 Plätzen"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/ephesus-2.jpg","cap":{"de":"Der Hadrianstempel an der Kuretenstraße"}}]},"pamukkale":{"long":{"de":["Siebzehn kalkgesättigte Thermalquellen ergießen sich seit zwei Millionen Jahren über diesen Hang und hinterlassen eine erstarrte Kaskade strahlend weißer Terrassen — die „Baumwollburg“. Die Römer, nie um ein heißes Bad verlegen, bauten auf dem Plateau darüber die Kurstadt Hierapolis; man reiste aus dem ganzen Reich zur Kur an — und viele blieben für immer, weshalb die Nekropole hier zu den größten antiken Friedhöfen Anatoliens zählt.","Steigen Sie barfuß durch die flachen blauen Becken hinauf (Schuhe in der Hand — diese Regel hält den Travertin weiß), dann erkunden Sie Hierapolis: ein herrlich steiles Theater, das Martyrium des Apostels Philippus und das Antike Becken, in dem man in warmem, perlendem Wasser über umgestürzten Marmorsäulen schwimmt. Zur goldenen Stunde färbt sich der ganze Hang rosa — die Tagesausflügler sind dann fort, und die Terrassen wirken am unwirklichsten."]},"getting":{"de":"20 Min. ab Denizli mit häufigen Dolmuş; Denizli hat einen Flughafen (DNZ) und Schnellzüge ab İzmir. Viele kombinieren den Besuch mit Ephesos."},"eat":{"de":"Das Dorf Pamukkale serviert ein üppiges Köy Kahvaltısı (Dorffrühstück) mit lokalem Honig; Denizli ist für sein langsam gegartes Lamm-Tandır bekannt."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/pamukkale-1.jpg","cap":{"de":"Terrassenbecken an der Travertinkante"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/pamukkale-2.jpg","cap":{"de":"Der weiße Hang vom Talgrund aus"}}]},"bodrum":{"long":{"de":["Das antike Halikarnassos schenkte der Welt zwei Wunder: den Historiker Herodot und das Mausoleum des Königs Mausolos — ein Grabmal, so prachtvoll, dass es zum Weltwunder wurde und jedem großen Grab seither den Namen gab. Seine Steine verbauten die Johanniter später in der Burg St. Peter, die heute den Hafen bewacht und das Museum für Unterwasserarchäologie beherbergt: bronzezeitliche Wracks, Glasfrachten und das Gold einer mykenischen Prinzessin, alles vom Grund der Ägäis geborgen.","Das moderne Bodrum ist das St-Tropez der Türkei: weiße Würfelhäuser unter Bougainvillea, eine Marina voller Yachten und hölzerner Gulets, Mandarinenhaine, Beachclubs und ein legendär langes Nachtleben. Die Halbinsel verbirgt stillere Ecken — Fischtische am Wasser in Gümüşlük, Surfbuchten bei Bitez, Steinruinen im Bergdorf Sandima. Der Klassiker ist die „Blaue Reise“: tagelang einsame Buchten ansegeln, wo die einzige Frage ist, wann man schwimmen geht."]},"getting":{"de":"Flug nach Milas-Bodrum (BJV), 40 Min. von der Stadt; Busse verbinden die gesamte Ägäisküste. In der Saison Fähren nach Kos und Rhodos."},"eat":{"de":"Fisch und Meze zum Sonnenuntergang in Gümüşlük, überall Mandarinen-Desserts — die Mandarinen der Halbinsel sind berühmt — und Lokma an der Marina."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/bodrum-1.jpg","cap":{"de":"Gulets und Yachten im Hafen von Bodrum"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/bodrum-2.jpg","cap":{"de":"Eine ruhige Marina auf der Halbinsel"}}]},"oludeniz":{"long":{"de":["Ölüdeniz heißt „totes Meer“ — nicht wegen Salz, sondern weil die Lagune spiegelglatt bleibt, selbst wenn Stürme das offene Mittelmeer jenseits der Sandbank aufwühlen. Als Naturpark geschützt, ist sie der meistfotografierte Ort der türkischen Küste: ein Bogen aus weißem Sand und Pinienwald um Wasser, das von Jade bis Tiefsaphir changiert. Kommen Sie früh — vor zehn ist das Licht am schönsten und die Sandbank am leersten.","Der Ort darüber ist zugleich eines der großen Gleitschirmzentren der Welt. Tandempiloten starten vom 1.900 Meter hohen Babadağ und kreisen eine halbe Stunde über die Lagune hinab; Erfahrung braucht es keine, nur Mut beim Startlauf. Vom Strand fahren Boote ins Schmetterlingstal, eine nur vom Meer erreichbare Schlucht, und der Lykische Weg — der berühmteste Fernwanderweg der Türkei — beginnt seine 540 km gleich oberhalb in Ovacık."]},"getting":{"de":"25 Min. mit dem Dolmuş ab Fethiye; nächster Flughafen ist Dalaman (DLM), 1 Std. entfernt mit Shuttlebussen."},"eat":{"de":"Auf dem Fischmarkt von Fethiye kauft man den Fang und lässt ihn an den umliegenden Tischen zubereiten; danach ein Eis auf der Promenade."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/oludeniz-1.jpg","cap":{"de":"Die Lagune und ihre berühmte Sandbank"}}]},"antalya":{"long":{"de":["Um 150 v. Chr. von einem pergamenischen König gegründet, empfängt Antalya seither Ankömmlinge — Hadrian bekam zu seinem Besuch 130 n. Chr. ein dreibogiges Marmortor, das noch heute der prächtigste Eingang nach Kaleiçi ist, der ummauerten Altstadt. Drinnen: ein Labyrinth aus osmanischen Villen, nach Mandarinen duftenden Höfen und einem kannelierten Minarett aus dem 13. Jh., alles um einen winzigen, in die Klippen gehauenen römischen Hafen gelegt.","Die Stadt ist zugleich das Tor zu den antiken Stätten Pamphyliens — Perges Säulenstraßen, das Theater von Aspendos, Sides Tempel am Meer — und zu einer Küste, die von den klippenstürzenden Düden-Wasserfällen bis zum langen Kiesbogen des Konyaaltı-Strandes unter dem Taurus reicht. Die Badesaison dauert von April bis November, und im Winter kann man morgens am Saklıkent Ski fahren und nach dem Mittagessen (zügig) schwimmen."]},"getting":{"de":"Der Flughafen Antalya (AYT) hat Direktflüge aus ganz Europa; Tram in die Altstadt in 40 Min. Perge und Aspendos sind kurze Tagesausflüge."},"eat":{"de":"Piyaz (weißer Bohnensalat mit Tahini) ist Antalyas Signaturgericht; essen Sie ihn mit Köfte im Basarviertel, danach Saft aus stadteigenen Orangen."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/antalya-1.jpg","cap":{"de":"Das römische Theater von Aspendos, ein leichter Tagesausflug"}}]},"side":{"long":{"de":["Side war der große Hafen Pamphyliens — Sklavenmarkt, Piratennest und in römischer Zeit eine Stadt, reich genug, ihre Hauptstraße mit Marmor zu pflastern und mit Kolonnaden zu säumen. Kleopatra und Marcus Antonius sollen sich hier getroffen haben. Die Ruinen wurden nie aufgegeben: Im 19. Jh. wuchs ein Fischerdorf mitten hinein, sodass man heute an einem Theater mit 15.000 Plätzen und einer byzantinischen Basilika vorbei zu Pensionsgärten und Strandbars spaziert.","An der äußersten Spitze der Halbinsel rahmen fünf wieder aufgerichtete Säulen des Apollontempels das Meer — bei Sonnenuntergang der romantischste Anblick des türkischen Mittelmeers. Zwanzig Minuten landeinwärts steht das Theater von Aspendos, das besterhaltene der römischen Welt, mit vollständigem Bühnenhaus und 41 Sitzreihen; wenn irgend möglich, erleben Sie dort an einem Sommerabend eine Oper oder ein Ballett."]},"getting":{"de":"75 km östlich des Flughafens Antalya; Busse und Dolmuş fahren über Manavgat. Aspendos und die Manavgat-Wasserfälle liegen am Weg."},"eat":{"de":"Fischrestaurants säumen den alten Hafen unterhalb des Tempels; im Landesinneren ist Manavgat für gegrillte Flussforelle und Çöp-Şiş-Spieße bekannt."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/side-1.jpg","cap":{"de":"Die Apollon-Säulen an der Spitze der Halbinsel"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/side-2.jpg","cap":{"de":"Aspendos — das besterhaltene Theater der römischen Welt"}}]},"cappadocia":{"long":{"de":["Drei Vulkane begruben dieses Hochplateau vor Jahrmillionen unter Asche; Wind und Regen meißelten aus dem weichen Tuff Minarette, Pilze und „Feenkamine“ — und Menschen vollendeten das Werk: Sie höhlten Wohnungen, Taubenschläge, Klöster und ganze unterirdische Städte bis acht Stockwerke tief aus, in denen sich frühe Christen samt Vieh, Weinpressen und Kapellen verbergen konnten. Im Freilichtmuseum von Göreme leuchten noch Fresken des 11. Jahrhunderts in Höhlenkirchen.","Fast alle fliegen: An ruhigen Morgen steigen über hundert Ballons im Morgengrauen über die Täler — eines der großen Schauspiele des Reisens. Buchen Sie einen lizenzierten Anbieter, planen Sie Reservemorgen für Windtage ein, und verbringen Sie die übrigen Tage mit Wanderungen durchs Rosental und Ihlara-Tal, in den unterirdischen Städten Kaymaklı oder Derinkuyu — und schlafen Sie im Höhlenhotel: Die Zimmer bleiben den ganzen Sommer natürlich kühl."]},"getting":{"de":"Flug nach Nevşehir (NAV) oder Kayseri (ASR), beide unter 1 Std. per Shuttle von Göreme. Nachtbusse ab Istanbul brauchen ca. 11 Std."},"eat":{"de":"Testi-Kebab — Fleisch im versiegelten Tontopf gegart, der am Tisch aufgeschlagen wird — dazu lokale Weine (Emir, Kalecik Karası) von Vulkanböden."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/cappadocia-1.jpg","cap":{"de":"Start im Morgengrauen über Göreme"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/cappadocia-2.jpg","cap":{"de":"Die Täler aus dem Ballonkorb"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/cappadocia-3.jpg","cap":{"de":"Die Felskirchen des Nationalparks Göreme"}}]},"konya":{"long":{"de":["„Komm, komm, wer immer du bist“ — die Einladung, die Dschalal ad-Din Rumi zugeschrieben wird, dem Sufi-Mystiker und Dichter des 13. Jahrhunderts, prägt seine Stadt bis heute. Konya war die Hauptstadt der Seldschuken-Sultane, als Rumis Familie auf der Flucht vor den Mongolen eintraf, und ihre schönste Architektur ist erhalten: der türkis überkuppelte Schrein, in dem er ruht, die Medresen İnce Minareli und Karatay mit sternenübersäten Fliesengewölben und die Alaeddin-Moschee auf ihrem uralten Hügel.","Rumis Anhänger gründeten den Mevlevi-Orden — die tanzenden Derwische —, deren Sema-Zeremonie Trauer in eine langsame, kreisende Meditation verwandelt. Erleben Sie eine echte am Samstagabend im Mevlâna-Kulturzentrum (es ist Gottesdienst, keine Show — nicht klatschen). Im Dezember folgt Şeb-i Arus, der Jahrestag von Rumis „Hochzeitsnacht“ mit dem Göttlichen, wenn Pilger und Poesiefreunde die Stadt füllen. Das moderne Konya ist fromm, wohlhabend und still — die Türkei in ihrer friedlichsten Form."]},"getting":{"de":"Schnellzüge erreichen Konya in ca. 2 Std. ab Ankara und 4,5 Std. ab Istanbul; der Flughafen (KYA) hat tägliche Istanbul-Flüge."},"eat":{"de":"Etli Ekmek — ein Meter dünnes Fladenbrot mit gewürztem Lamm — dazu Fırın Kebabı (ofengegartes Hammelfleisch) und Okrasuppe, Konyas Hochzeitsklassiker."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/konya-1.jpg","cap":{"de":"Die Sema — Andacht in Bewegung"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/konya-2.jpg","cap":{"de":"Rumis türkisgekacheltes Mausoleum"}}]},"sumela":{"long":{"de":["Der Legende nach gründeten zwei athenische Mönche, von einer Marienvision geleitet, Sumela im Jahr 386 auf einem Felsband, das kein vernünftiger Baumeister wählen würde: eine senkrechte Wand, 300 Meter über dem Altındere-Tal. Was dort über sechzehn Jahrhunderte wuchs — Kapellen, Küchen, Zellen, eine heilige Quelle, eine Bibliothek —, klebt am Fels wie ein Schwalbennest, und die Felsenkirche leuchtet mit Fresken von Propheten, Aposteln und byzantinischen Kaisern, von Malergenerationen übereinandergeschichtet.","1923 leerte sich das Kloster mit dem Bevölkerungsaustausch, doch die Restaurierung hat die Fresken zu lebhaftem Leben zurückgebracht. Die halbe Erfahrung ist die Lage: der Aufstieg durch Buchen- und Kiefernwald, Wolken, die unter den Gebäuden treiben, das Rauschen des Baches tief unten. Dies ist die grüne, feuchte, alpine Türkei — kombinieren Sie sie mit den Teeterrassen von Rize und dem Bergsee Uzungöl zu einer vollen Schwarzmeer-Runde."]},"getting":{"de":"45 km von Trabzon (Flughafen TZX); Touren und Dolmuş fahren täglich. Ein Shuttle übernimmt den letzten Anstieg vom Parkplatz im Tal."},"eat":{"de":"Schwarzmeer-Klassiker: Muhlama (Maisgrieß-Käse-Fondue), frische Sardellen in der Saison und Laz Böreği zum Dessert — mit endlosem Rize-Tee."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/sumela-1.jpg","cap":{"de":"Das Kloster von der Talstraße aus"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/sumela-2.jpg","cap":{"de":"Die bewaldeten Hänge des Nationalparks Altındere"}}]},"safranbolu":{"long":{"de":["Safranbolu wurde durch zweierlei reich: Safran von den umliegenden Feldern — noch immer eines der kostbarsten Gewürze der Welt — und seine Lage an der osmanischen Karawanenstraße von Istanbul zum Schwarzen Meer. Kaufleute steckten ihren Reichtum in rund 2.000 Fachwerk-Konaks: drei Stockwerke, auskragende Obergeschosse, geschnitzte Decken, Innenbecken zur Kühlung. Und weil das 20. Jahrhundert an der Stadt vorbeizog, blieb fast alles intakt — 1994 kam die UNESCO-Listung.","Übernachten Sie in einem restaurierten Konak: knarrende Dielen, niedrige Türen, Frühstück im schattigen Hof. Bummeln Sie durch die Handwerksgasse der Yemeniciler-Arkade, trinken Sie Kaffee in der Karawanserei Cinci Han aus dem 17. Jh., steigen Sie für das klassische Ziegeldach-Panorama auf den Hıdırlık-Hügel und kaufen Sie Safran-Lokum von Familien, die die Krokusse seit Generationen anbauen. Im Winter macht Schnee auf den Dächern daraus ein Märchen."]},"getting":{"de":"Ca. 2 Std. mit Auto oder Bus ab Ankara, 5 Std. ab Istanbul; Busse halten in Kıranköy, kurz oberhalb des historischen Çarşı-Viertels."},"eat":{"de":"Safran-Lokum und Safrantee, Kuyu Kebabı (im Erdofen gegartes Lamm) und Bükme-Gebäck — danach türkischer Kaffee im Hof der Karawanserei."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/safranbolu-1.jpg","cap":{"de":"Konak-Villen an einer Kopfsteingasse"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/safranbolu-2.jpg","cap":{"de":"Der Uhrturm über der Altstadt"}}]},"uzungol":{"long":{"de":["Ein Erdrutsch staute vor Jahrhunderten den Haldizen-Bach und hinterließ Uzungöl — den „langen See“ —, ein Band grünen Wassers am Grund eines steilen Hochtals, mit einem Dorf und einer schlanken Moschee am Ufer und Fichtenwald, der ringsum in den Nebel steigt. Auf 1.090 Metern bleibt die Luft selbst im August kühl, und die Szenerie erinnert eher an Alpen oder Kaukasus als an das übliche Türkei-Bild.","Die flache Seerunde ist in einer knappen Stunde gelaufen — danach hinauf: Yayla-Wege (Almstraßen) führen nach Şekersu und weiter, wo Hirten die Sommer verbringen und die Wolken unter einem liegen. Das Dorf ist eine bequeme Basis für die ganze Region — das Sumela-Kloster, die Ayder-Hochebene und das Teeland von Rize liegen alle in Tagesausflugsweite. Kommen Sie möglichst unter der Woche oder außerhalb der Saison; Sommerwochenenden sind lebhaft und laut."]},"getting":{"de":"99 km vom Flughafen Trabzon über Of und das Solaklı-Tal — etwa 1,5 Std. mit Auto, Minibus oder Tagestouren."},"eat":{"de":"Frische Forelle aus den Seezuchten, Muhlama, das in Kupferpfannen brodelt, lokale Butter und Honig zum Frühstück — Bergküche vom Feinsten."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/uzungol-1.jpg","cap":{"de":"Die Moschee am See in ihrem Tal"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/uzungol-2.jpg","cap":{"de":"Der Blick von der Aussichtsplattform"}}]},"ani":{"long":{"de":["Um das Jahr 1000 zählte Ani vielleicht 100.000 Einwohner und handelte an der Seidenstraße auf Augenhöhe mit Konstantinopel und Kairo. Als Hauptstadt des bagratidischen Armenierreichs war es so dicht mit Heiligtümern besetzt, dass Chronisten es die Stadt der 1001 Kirchen nannten. Dann kamen Eroberungen — Byzantiner, Seldschuken, Mongolen —, ein Erdbeben 1319, verschobene Handelswege und schließlich Stille. Was blieb, steht allein auf einem Grasplateau, umringt von der Schlucht des Achurjan, direkt an der Grenze zu Armenien.","Man wandert von Ruine zu Ruine, begleitet von Feldlerchen: die Kathedrale, deren Baumeister auch die Kuppel der Hagia Sophia reparierte, die runde Gregorskirche mit Fresken vom Boden bis zur Decke, ein Seldschukenpalast, eine Moschee mit Schluchtblick, Reste einer 1.600 Jahre alten Brücke. Wenige Orte der Welt sind so aufgeladen mit versunkener Größe. Nehmen Sie Wasser, Sonnenschutz und mindestens einen halben Tag mit; kombinieren Sie Ani mit Kars' baltisch anmutender Steinarchitektur und den berühmten Honig-Käse-Frühstücken."]},"getting":{"de":"45 km östlich von Kars (Flughafen KSY, Flüge ab Istanbul und Ankara); Taxis und kleine Touren fahren hinaus, oder Sie nehmen die leeren Steppenstraßen selbst."},"eat":{"de":"Kars ist die Käsehauptstadt der Türkei — gereifter Gravyer, Honig von Bergwiesen und im Winter Gans nach lokaler Art."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/ani-1.jpg","cap":{"de":"Die Gregorskirche über der Schlucht"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/ani-2.jpg","cap":{"de":"Mittelalterliche Fresken in Tigran Honents"}}]},"van":{"long":{"de":["Der Vansee ist ein Binnenmeer, siebenmal so groß wie der Genfersee, sein Soda-Wasser so mineralreich, dass man Wäsche darin waschen kann — und den ganzen Sommer schwerelos darin schwimmt. An seinen Ufern stieg und fiel das eisenzeitliche Reich Urartu; die Festung Van, ihre Zitadelle aus dem 9. Jh. v. Chr., zieht sich noch heute über einen Felsrücken oberhalb der modernen Stadt, mit Keilinschriften in der Klippe.","Das Juwel des Sees ist die Insel Akdamar, wo die armenische Heilig-Kreuz-Kirche aus dem 10. Jh. ihre Bibel außen trägt: Jona und der Wal, David und Goliath, Adam und Eva — alles in Relief auf rosafarbenem Stein, vor der Kulisse des schneebedeckten Süphan. Fähren machen die 20-minütige Überfahrt den ganzen Tag. In der Stadt halten Sie Ausschau nach den berühmt flauschigen, schwimmenden Van-Katzen — ein Auge blau, eins bernsteinfarben — und widmen Sie einen ganzen Vormittag dem Van-Frühstück, einer Institution aus vierzig Tellerchen."]},"getting":{"de":"Der Flughafen Van (VAN) hat Direktflüge ab Istanbul und Ankara. Die Akdamar-Fähren legen in Gevaş ab, 45 km südwestlich der Stadt."},"eat":{"de":"Das Van-Frühstück: Otlu Peynir (Kräuterkäse), Kaymak mit Honig, Murtuğa und endloser Tee — dazu gegrillte Perlmugil, der Fisch des Sees."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/van-1.jpg","cap":{"de":"Die Insel Akdamar mit der Heilig-Kreuz-Kirche"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/van-2.jpg","cap":{"de":"Biblische Reliefs an den Kirchenwänden"}}]},"gobekli":{"long":{"de":["Göbekli Tepe hat die Menschheitsgeschichte umgeschrieben. Um 9600 v. Chr. — vor Ackerbau, Töpferei oder Rad — schleppten Jäger und Sammler zehn Tonnen schwere Kalksteinpfeiler auf diesen Hügel und errichteten Ringe aus behauenen Megalithen: Füchse, Kraniche, Skorpione, Schlangen und schleichende Leoparden, Arme und Hände über die T-Steine gefaltet, als wären sie Wesen. Lange galt: erst Sesshaftigkeit, dann Religion — hier kam offenbar der Tempel zuerst, und Dörfer entstanden, um ihm zu dienen.","Nur ein Bruchteil ist ausgegraben — Geophysik zeigt mindestens fünfzehn weitere Kreise im Boden —, man sieht also nur den sichtbaren Rand von etwas viel Größerem. Stege umrunden die Hauptanlage unter ihrem Schutzdach; kommen Sie früh oder spät für weiches Licht und wenig Betrieb. In Şanlıurfa birgt danach das großartige Archäologiemuseum die Funde (darunter die älteste lebensgroße Menschenstatue), und die heiligen Karpfenteiche von Balıklıgöl glühen in der Dämmerung. Karahan Tepe, eine noch archaischer wirkende Schwesterstätte, liegt eine Stunde entfernt."]},"getting":{"de":"22 km von Şanlıurfa (Flughafen GNY); Taxis, Touren und ein Shuttle ab dem Museum fahren täglich. Früh besuchen — die Sommerhitze ist heftig."},"eat":{"de":"Urfa ist eine eigene kulinarische Pilgerfahrt: Çiğ Köfte nach Originalart, Lahmacun aus Holzöfen, Isot-Paprika in allem, danach Künefe."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/gobekli-1.jpg","cap":{"de":"Die T-Pfeiler von Anlage C"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/gobekli-2.jpg","cap":{"de":"Das Tierrelief des Geierstelen-Pfeilers"}}]},"nemrut":{"long":{"de":["Antiochos I. von Kommagene regierte ein kleines Pufferreich zwischen Rom und Persien — und beschloss, wie keines von beiden erinnert zu werden. Auf seinem höchsten Berg ließ er einen 50-Meter-Grabhügel aus Schotter aufschütten, flankiert von Terrassen, auf denen er sich zwischen Zeus, Apollon und Herakles thronen ließ — ein selbsterklärter Gott mit Stammbaum bis zu Alexander und Dareios. Erdbeben stürzten die Köpfe von den neun Meter hohen Körpern, und genau dieses Bild lockt alle her: kolossale Steingesichter, die gelassen über ein Meer aus Bergen blicken.","Das Ritual ist der eigentliche Sinn: im Dunkeln hinauffahren, die letzten 600 Meter Weg steigen und zusehen, wie der Sonnenaufgang die Ostterrasse entzündet (oder der Untergang die Westterrasse). Selbst im August gehört eine richtige Jacke ins Gepäck — der Gipfelwind beißt. Seine Grabkammer im Innern des Hügels wurde nie gefunden. Auf dem Rückweg lohnen die Römerbrücke von Cendere und der Tumulus von Karakuş; kombinieren Sie Nemrut am besten mit Göbekli Tepe und Şanlıurfa."]},"getting":{"de":"Basis ist Kahta oder das Dorf Karadut (Flughafen Adıyaman 1,5 Std. entfernt); die Straße ist etwa Mai–Oktober offen."},"eat":{"de":"Die Pensionen in Karadut kochen Hausmannskost für Sonnenaufgangs-Gäste; in Adıyaman danach Çiğ Köfte und pistazienreiche Desserts probieren."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/nemrut-1.jpg","cap":{"de":"Sonnenaufgang auf der Ostterrasse"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/nemrut-2.jpg","cap":{"de":"Die Götterköpfe zu Füßen ihres Königs"}}]},"mardin":{"long":{"de":["Mardin ergießt sich in Terrassen honigfarbenen Kalksteins über einen Hang, jedes Dach eine Aussichtsterrasse über die mesopotamische Ebene Richtung Syrien — in der Dämmerung löst sich der Blick in goldenen Dunst auf. Araber, Kurden, Türken, syrische Christen und einst eine große jüdische Gemeinde bauten diese Stadt gemeinsam, und man sieht es: Minarette und Kirchtürme teilen sich die Silhouette, und in den eselsbreiten Basargassen hört man fünf Sprachen.","Die Steinmetzkunst ist der Ruhm der Stadt — schauen Sie hinauf zu den Portalen, den Medresen Zinciriye und Kasımiye, dem kannelierten Minarett der Großen Moschee. Kurz vor der Stadt hält das safranfarbene Kloster Deyrulzafaran seit dem 5. Jahrhundert Gottesdienste auf Aramäisch, der Sprache Jesu; tiefer im Tur Abdin ist Mor Gabriel eines der ältesten aktiven Klöster der Erde. Kaufen Sie filigranes Silber (Telkari), kosten Sie bitteren Mırra-Kaffee und übernachten Sie in einem Steinpalais mit der Ebene unterm Fenster."]},"getting":{"de":"Der Flughafen Mardin (MQM) liegt 20 Min. von der Altstadt; Busse verbinden Şanlıurfa (3 Std.) und Diyarbakır (1,5 Std.) zur Südost-Rundreise."},"eat":{"de":"Kaburga Dolması (mit Reis gefüllte Lammrippen), Kirsch-Kebab, Mandelkonfekt und bitterer Mırra-Kaffee aus der Messingkanne."},"gallery":[{"src":"https://api.bubixo.com/discover-turkiye/assets/g/mardin-1.jpg","cap":{"de":"Steinpaläste in Terrassen über der Ebene"}},{"src":"https://api.bubixo.com/discover-turkiye/assets/g/mardin-2.jpg","cap":{"de":"Reliefierte Fassaden in der Altstadt"}}]}};
var UZUNGOL = {"id":"uzungol","img":"https://api.bubixo.com/discover-turkiye/assets/uzungol.jpg","region":"north","unesco":false,"name":{"de":"Uzungöl"},"desc":{"de":"Ein spiegelglatter Bergsee auf 1.090 m, mit einer Moschee am Ufer und Fichtenwald, der in den Nebel steigt — das Postkartenmotiv der Schwarzmeerregion und selbst im Hochsommer angenehm kühl."},"loc":{"de":"Çaykara, Trabzon"},"best":{"de":"Mai–Okt; neblige Morgen sind der Zauber"},"tip":{"de":"Übernachten Sie — der See ist am stillsten, bevor die Tagesbusse kommen und nachdem sie fort sind."}};
